    # "SR with Meta-Analysis": {"rob_tool": "amstar2",  "reporting_guideline": "prisma2020", "initial_grade": "High"},
    # "Diagnostic Accuracy":   {"rob_tool": "quadas2",  "reporting_guideline": "stard",      "initial_grade": "Low"},
